    'Markieren Sie alles, was zurückgegeben bzw. entzogen werden muss. Aus einem früheren Auftrag übernommene Einträge sind bereits ausgewählt.' => 'Sélectionnez tout ce qui doit être restitué ou retiré. Les entrées reprises d’une demande antérieure sont déjà sélectionnées.',
    'Markieren Sie, was während der Abwesenheit deaktiviert bzw. pausiert werden soll. Bei Geräten können Sie in der Bemerkung angeben, ob sie beim Mitarbeitenden verbleiben.' => 'Sélectionnez ce qui doit être désactivé ou suspendu pendant l’absence. Pour le matériel, vous pouvez indiquer dans la remarque s’il reste chez le collaborateur.',
