    'Mit Kundennummer werden vorhandene Kunden beim nächsten Import aktualisiert statt doppelt angelegt' => 'Avec un numéro client, les clients existants sont mis à jour lors de l’import suivant au lieu d’être créés en double',
    'Mit Passwort sind die ZIP-Archive verschlüsselt. Zum Öffnen z. B. 7-Zip verwenden – der Windows-Explorer kann AES-verschlüsselte ZIPs nicht öffnen. Passwort gut aufbewahren, ohne es ist die Sicherung unbrauchbar.' => 'Avec un mot de passe, les archives ZIP sont chiffrées. Utilisez p. ex. 7-Zip pour les ouvrir – l’Explorateur Windows ne peut pas ouvrir les ZIP chiffrés en AES. Conservez bien le mot de passe ; sans lui, la sauvegarde est inutilisable.',
    'Mit Pflichtangaben – zweizeilig' => 'Avec mentions obligatoires – deux lignes',
    'Mit ausgewählten Firmen sieht der Administrator nur deren Daten. Firmenübergreifendes (neue Firmen, eigene Apps, zentrales Postfach, Portal-Sicherungen, Katalogeinträge für alle Firmen) bleibt Administratoren mit Zugriff auf alle Firmen vorbehalten.' => 'Avec des entreprises sélectionnées, l’administrateur ne voit que leurs données. Les éléments transversaux (nouvelles entreprises, applications propres, boîte centrale, sauvegardes du portail, entrées de catalogue pour toutes les entreprises) restent réservés aux administrateurs ayant accès à toutes les entreprises.',
    'Mit dem gewünschten Google-Konto auf' => 'Avec le compte Google souhaité, allez sur',
    'Mit einem API-Schlüssel können andere Programme (z. B. CRM, Warenwirtschaft, Zapier oder n8n) Kunden dieser Firma lesen und – wenn erlaubt – anlegen, ändern oder löschen.' => 'Avec une clé API, d’autres programmes (p. ex. CRM, ERP, Zapier ou n8n) peuvent lire les clients de cette entreprise et – si autorisé – les créer, modifier ou supprimer.',
