    'Nach Auswahl von Abteilung und Position werden die üblichen Einträge automatisch vorausgewählt. Sie können die Auswahl anpassen.' => 'Après le choix du service et du poste, les entrées habituelles sont présélectionnées automatiquement. Vous pouvez adapter la sélection.',
    'Nach dem Speichern melden Sie sich mit dem Google-Konto an, über das versendet werden soll. Das Portal erhält nur das Recht, E-Mails zu senden, und kann keine E-Mails lesen.' => 'Après l’enregistrement, connectez-vous avec le compte Google à utiliser pour l’envoi. Le portail obtient uniquement le droit d’envoyer des e-mails et ne peut pas les lire.',
    'Nach dem Speichern melden Sie sich mit dem Microsoft-Konto an, über das versendet werden soll (z. B. it@ihre-firma.de). Das Portal erhält nur das Recht, E-Mails zu senden, und kann keine E-Mails lesen.' => 'Après l’enregistrement, connectez-vous avec le compte Microsoft à utiliser pour l’envoi (p. ex. it@votre-entreprise.fr). Le portail obtient uniquement le droit d’envoyer des e-mails et ne peut pas les lire.',
    'Nach „Freigegeben“ oder „Storniert“ ist der Auftrag abgeschlossen. Spätere Änderungen gehen nur noch über einen Änderungsantrag, den die Firma freigibt.' => 'Après « Validée » ou « Annulée », la demande est clôturée. Les modifications ultérieures passent uniquement par une demande de modification acceptée par l’entreprise.',
