    'Waren Sie das nicht? Bitte wenden Sie sich sofort an Ihren IT-Dienstleister.' => 'Ce n’était pas vous ? Contactez immédiatement votre prestataire informatique.',
    'Wartet auf die Freigabe durch einen Firmen-Administrator oder die Person, die den Auftrag eingereicht hat.' => 'En attente d’acceptation par un administrateur de l’entreprise ou la personne qui a envoyé la demande.',
    'Wartet ein Ticket zu lange auf eine Reaktion der Bearbeiter, bekommt zuerst der gebuchte Bearbeiter (sonst die Queue) eine Erinnerung, danach die Teamleitung der Queue und nach der doppelten Eskalationszeit die Firmen-Administratoren. Die Uhr steht bei Rückfrage, Zurückgestellt und Gelöst und beginnt neu, sobald ein Bearbeiter antwortet oder das Ticket bucht. 0 = aus.' => 'Si un ticket attend trop longtemps une réaction des responsables, le responsable attribué (sinon la file) reçoit d’abord un rappel, puis le chef d’équipe de la file et, après deux fois le délai d’escalade, les administrateurs de l’entreprise. L’horloge s’arrête pendant Question, En attente et Résolu et redémarre dès qu’un responsable répond ou prend le ticket. 0 = désactivé.',
    'Wartet seit' => 'En attente depuis',
    'Wartet zu lange' => 'Attente trop longue',
