    'E-Mail-Eingang' => 'Réception par e-mail',
    'Tickets per E-Mail: Mails an ein Postfach werden zu Tickets, Antworten mit der Ticketnummer im Betreff landen im Verlauf. Absender müssen ein Konto in der Firma haben; Mails unbekannter Absender kommen in die Prüfliste. Abgerufen werden ungelesene Mails im Posteingang, danach sind sie als gelesen markiert – das Postfach sollte daher nur für die Tickets genutzt werden.' => 'Tickets par e-mail : les e-mails envoyés à une boîte deviennent des tickets, les réponses avec le numéro de ticket dans l\'objet sont ajoutées à l\'historique. Les expéditeurs doivent avoir un compte dans l\'entreprise ; les e-mails d\'expéditeurs inconnus vont dans la liste de contrôle. Les e-mails non lus de la boîte de réception sont récupérés puis marqués comme lus – la boîte ne doit donc servir qu\'aux tickets.',
