    'Die ersten 100 von {n}; alle stehen im CSV-Export.' => 'Les 100 premiers sur {n} ; tous figurent dans l\'export CSV.',
    'Mitarbeiter-Statistik' => 'Statistiques par collaborateur',
    'Die Mitarbeiter-Statistik ist ausgeschaltet. Die Auswertung zeigt deshalb nur Zahlen je Queue, Dringlichkeit, Kategorie und Abteilung.' => 'Les statistiques par collaborateur sont désactivées. L\'évaluation n\'affiche donc que des chiffres par file, urgence, catégorie et service.',
    'Einschalten unter Queues & Einstellungen' => 'Activer sous Files & paramètres',
    'Antworten' => 'Réponses',
    'erste Antworten' => 'premières réponses',
    'Lösungszeit (Median)' => 'Délai de résolution (médiane)',
    'Keine Bearbeitungen im Zeitraum.' => 'Aucun traitement sur la période.',
    'Antworten und erste Antworten zählen für Tickets, die im Zeitraum angelegt wurden; „gelöst“ für Tickets, die im Zeitraum gelöst wurden. Wer ein Ticket nur als Ersteller bestätigt, zählt nicht.' => 'Les réponses et premières réponses comptent pour les tickets créés sur la période ; « résolus » pour les tickets résolus sur la période. Confirmer un ticket en tant qu\'auteur ne compte pas.',
    'Mitarbeiter-Statistik in der Auswertung zeigen (Tickets und Zeiten je Bearbeiter)' => 'Afficher les statistiques par collaborateur dans l\'évaluation (tickets et durées par personne chargée du traitement)',
    'Hinweis: Eine Auswertung, mit der sich Leistung oder Verhalten einzelner Mitarbeiter überwachen lässt, ist bei Firmen mit Betriebsrat mitbestimmungspflichtig und berührt den Datenschutz. Ausgeschaltet zeigt die Auswertung nur Zahlen je Queue, Dringlichkeit, Kategorie und Abteilung.' => 'Remarque : une évaluation permettant de surveiller les performances ou le comportement de collaborateurs individuels est soumise à la codécision dans les entreprises dotées d\'un comité d\'entreprise et concerne la protection des données. Désactivée, l\'évaluation n\'affiche que des chiffres par file, urgence, catégorie et service.',
    'Diese Einsicht und die Mitarbeiter-Statistik kann nur ein Administrator der Firma ein- oder ausschalten.' => 'Seul un administrateur de l\'entreprise peut activer ou désactiver cet accès et les statistiques par collaborateur.',
