    'nicht zurückgegeben' => 'non rendu',
    'Ich bestätige den Erhalt der oben aufgeführten Geräte in ordnungsgemäßem Zustand. Die Geräte bleiben Eigentum der Firma, sind sorgfältig zu behandeln und ausschließlich dienstlich zu nutzen. Verlust oder Schäden melde ich unverzüglich. Beim Austritt gebe ich alle Geräte vollständig zurück.' => 'Je confirme avoir reçu les appareils ci-dessus en bon état. Les appareils restent la propriété de l\'entreprise, doivent être manipulés avec soin et utilisés uniquement à des fins professionnelles. Je signalerai immédiatement toute perte ou tout dommage. À mon départ, je restituerai l\'ensemble des appareils.',
    'Die oben aufgeführten Geräte wurden im angegebenen Zustand zurückgegeben.' => 'Les appareils ci-dessus ont été rendus dans l\'état indiqué.',
