    'Vergeben am' => 'Attribué le',
    'Bitte eine CSV-Datei auswählen (höchstens 5 MB).' => 'Veuillez choisir un fichier CSV (5 Mo max.).',
    'Die Spalte „{x}“ fehlt. Bitte die erste Zeile mit den Spaltennamen prüfen.' => 'La colonne « {x} » est manquante. Veuillez vérifier la première ligne avec les noms de colonnes.',
