    '{n} Einträge angelegt, {u} aktualisiert, {s} übersprungen.' => '{n} entrées créées, {u} mises à jour, {s} ignorées.',
    'Zur Übersicht' => 'Vers l’aperçu',
    '{n} Zeilen erkannt. Zugeordnete Spalten:' => '{n} lignes détectées. Colonnes associées :',
    'Nicht erkannt und ignoriert:' => 'Non reconnues et ignorées :',
    'Jetzt importieren' => 'Importer maintenant',
    'CSV-Datei mit einer Kopfzeile (Trennzeichen ; oder ,), z. B. aus Excel „CSV UTF-8“. Erkannte Spalten:' => 'Fichier CSV avec une ligne d’en-tête (séparateur ; ou ,), p. ex. depuis Excel « CSV UTF-8 ». Colonnes reconnues :',
    'Pflicht ist „Produkt“. Gibt es ein Produkt mit gleicher Vertragsnummer schon, wird es aktualisiert. Art: Abo, Kauflizenz oder Wartung; Zeitraum: Monat, Jahr oder einmalig.' => '« Produit » est obligatoire. Si un produit avec le même numéro de contrat existe déjà, il est mis à jour. Type : abonnement, licence perpétuelle ou maintenance ; période : mois, an ou unique.',
    'Pflicht ist „Typ“. Unbekannte Typen und Standorte werden angelegt. Gibt es die Inventarnummer schon, wird das Gerät aktualisiert. Mitarbeiter werden über Personalnummer oder E-Mail zugeordnet. Ohne Inventarnummer wird automatisch nummeriert.' => '« Type » est obligatoire. Les types et sites inconnus sont créés. Si le numéro d’inventaire existe déjà, l’appareil est mis à jour. Les collaborateurs sont associés par matricule ou e-mail. Sans numéro d’inventaire, la numérotation est automatique.',
    'Aktuellen Bestand als Vorlage exportieren' => 'Exporter l’inventaire actuel comme modèle',
    'Vorschau anzeigen' => 'Afficher l’aperçu',
    'Zeile {n}: Typ fehlt.' => 'Ligne {n} : type manquant.',
    'Zeile {n}: Produkt fehlt.' => 'Ligne {n} : produit manquant.',
    'Mindestbestand' => 'Stock minimum',
    'Der Mindestbestand wurde gespeichert.' => 'Le stock minimum a été enregistré.',
    'Vorlauf für Erinnerungen (Tage)' => 'Délai des rappels (jours)',
    'So viele Tage vor Lizenzende, Kündigungsfrist und Garantieende erscheint der Punkt unter „Demnächst fällig“ und die Firmen-Admins bekommen eine E-Mail – mit Einsicht auch der IT-Dienstleister.' => 'Ce nombre de jours avant la fin de licence, le délai de résiliation et la fin de garantie, le point apparaît sous « Bientôt dû » et les administrateurs reçoivent un e-mail – avec accès accordé, le prestataire informatique aussi.',
    'Liegen an einem Lager weniger Geräte eines Typs als hier angegeben, erscheint eine Bestandswarnung und die Firmen-Admins und Gruppen mit „bearbeiten“ bekommen eine E-Mail. Leer oder 0 = keine Warnung.' => 'Si un stock contient moins d’appareils d’un type que la valeur indiquée, un avertissement apparaît et les administrateurs ainsi que les groupes avec « modifier » reçoivent un e-mail. Vide ou 0 = pas d’avertissement.',
    'Bitte zuerst einen Standort als Lager anlegen.' => 'Veuillez d’abord créer un site comme stock.',
    'Mindestbestand speichern' => 'Enregistrer le stock minimum',
