    'Einsicht für den IT-Dienstleister' => 'Accès pour le prestataire informatique',
    'Unser IT-Dienstleister darf unsere Verträge sehen und pflegen' => 'Notre prestataire informatique peut consulter et gérer nos contrats',
    '… und dabei auch die Kosten sehen' => '… y compris les coûts',
    'Ohne diese Einsicht sieht der IT-Dienstleister keine Verträge. Ihre eigenen Rechte über Gruppen gelten unabhängig davon.' => 'Sans cet accès, le prestataire informatique ne voit aucun contrat. Vos propres droits par groupe s’appliquent indépendamment.',
    'Firmen-Administratoren dürfen immer alles. Weitere Rechte vergeben Sie je Gruppe (Abteilung); wer mehreren Gruppen angehört, bekommt das höchste Recht. Preise sieht nur, wer „Kosten sehen“ hat.' => 'Les administrateurs de l’entreprise peuvent toujours tout faire. Vous attribuez d’autres droits par groupe (service) ; les membres de plusieurs groupes obtiennent le droit le plus élevé. Seuls ceux qui ont « Voir les coûts » voient les prix.',
