    'Alle Verträge der Firma an einem Ort: Laufzeiten, Kündigungsfristen, Kosten und Dokumente – damit sich nichts unbemerkt verlängert.' => 'Tous les contrats de l’entreprise au même endroit : durées, délais de résiliation, coûts et documents – pour que rien ne se renouvelle à votre insu.',
    'Verträge der Firmen; nur mit Einsicht-Freigabe der Firma, Kosten nur mit eigener Freigabe' => 'Contrats des entreprises ; uniquement avec l’accès accordé par l’entreprise, coûts uniquement avec une autorisation distincte',
    // Verträge & Laufzeiten (Stufe 2)
