    'ab {d}: {x}' => 'à partir du {d} : {x}',
    'Grundpreis ab Vertragsbeginn, wie auf der Rechnung (z. B. netto). Spätere Preisänderungen tragen Sie in der Preishistorie mit „gültig ab“ ein.' => 'Prix de base dès le début du contrat, comme sur la facture (p. ex. HT). Saisissez les changements de prix ultérieurs dans l’historique des prix avec « valable à partir du ».',
    'Bitte angeben, ab wann der neue Preis gilt.' => 'Veuillez indiquer à partir de quand le nouveau prix s’applique.',
    'Der neue Preis muss nach dem Vertragsbeginn gelten. Den Preis ab Beginn ändern Sie oben im Vertrag.' => 'Le nouveau prix doit s’appliquer après le début du contrat. Modifiez le prix initial plus haut dans le contrat.',
