    'Gepflegt werden sie weiter im Inventar. Ist eine Lizenz mit einem Vertrag verknüpft, erscheint nur der Vertrag. Die Lizenzen sieht nur, wer im Inventar Leserecht hat.' => 'Elles restent gérées dans l’inventaire. Si une licence est liée à un contrat, seul le contrat apparaît. Seuls ceux qui ont un droit de lecture sur l’inventaire voient les licences.',
