    // Verträge & Laufzeiten (Stufe 3)
    'Fristenkalender' => 'Calendrier des échéances',
    'An Fristen erinnert das Portal per E-Mail. Die Kündigung mit Freigabe folgt in der nächsten Stufe.' => 'Le portail rappelle les échéances par e-mail. La résiliation avec validation suivra à la prochaine étape.',
    'Bitte gültige E-Mail-Adressen angeben (höchstens {n}).' => 'Veuillez indiquer des adresses e-mail valides ({n} max.).',
    'Für den automatischen Versand bitte Empfänger angeben.' => 'Veuillez indiquer des destinataires pour l’envoi automatique.',
    'Erinnerungen und Fristenübersicht' => 'Rappels et récapitulatif des échéances',
    'So viele Tage vor dem Ende einer Kündigungsfrist oder eines Vertrags erscheint der Punkt unter „Demnächst fällig“, und die Firmen-Admins und die verantwortliche Person bekommen eine E-Mail – bei Einsicht auch Ihr IT-Dienstleister für die Verträge, die er betreut. Preisänderungen melden wir 14 Tage vorher an alle mit „Kosten sehen“.' => 'Ce nombre de jours avant la fin d’un délai de résiliation ou d’un contrat, l’élément apparaît sous « Bientôt dû » et les administrateurs de l’entreprise ainsi que la personne responsable reçoivent un e-mail – avec accès, aussi votre prestataire informatique pour les contrats qu’il gère. Les changements de prix sont annoncés 14 jours à l’avance à tous ceux qui ont « Voir les coûts ».',
    'Fristenübersicht als PDF automatisch senden' => 'Envoyer automatiquement le récapitulatif des échéances en PDF',
