    // Verträge & Laufzeiten (Stufe 6)
    '„Kosten sehen“ und „Freigabe Kündigung“ wirken nur zusammen mit „ansehen“ oder „bearbeiten“.' => '« Voir les coûts » et « Valider la résiliation » ne s’appliquent qu’avec « consulter » ou « modifier ».',
    'Neue Vertragsart angelegt: {x}' => 'Nouveau type de contrat créé : {x}',
    'Unbekannter Status „{x}“ (erlaubt: aktiv, gekündigt, verlängert, beendet).' => 'Statut inconnu « {x} » (autorisés : actif, résilié, renouvelé, terminé).',
    'Status nicht geändert: Für den Vertrag läuft gerade eine Kündigung.' => 'Statut non modifié : une résiliation est en cours pour ce contrat.',
    'Ungültiges Datum „{x}“ (TT.MM.JJJJ oder JJJJ-MM-TT).' => 'Date invalide « {x} » (JJ.MM.AAAA ou AAAA-MM-JJ).',
    '„{f}“ muss eine ganze Zahl sein.' => '« {f} » doit être un nombre entier.',
    'Unbekannte Einheit „{x}“ (Tage, Wochen, Monate).' => 'Unité inconnue « {x} » (jours, semaines, mois).',
    'Unbekannte Betreuung „{x}“ (IT-Dienstleister, Firma selbst oder Name eines Dienstleisters aus den Tickets).' => 'Gestion inconnue « {x} » (prestataire informatique, l’entreprise elle-même ou nom d’un prestataire des tickets).',
    'Kosten ignoriert: Dafür fehlt das Recht „Kosten sehen“.' => 'Coûts ignorés : le droit « Voir les coûts » manque.',
    'Unbekannter Zeitraum „{x}“ (Monat, Quartal, Jahr, einmalig).' => 'Période inconnue « {x} » (mois, trimestre, année, unique).',
    'Grundpreis' => 'Prix de base',
    'Zeile {n}' => 'Ligne {n}',
    'Eintrag {n}: ' => 'Entrée {n} : ',
    '{n} Verträge angelegt, {u} aktualisiert, {s} unverändert, {e} mit Fehlern übersprungen.' => '{n} contrats créés, {u} mis à jour, {s} inchangés, {e} ignorés en raison d’erreurs.',
    'aktualisieren' => 'mettre à jour',
    '… und {n} weitere Zeilen.' => '… et {n} lignes de plus.',
    'Verträge importieren' => 'Importer des contrats',
    'Pflicht sind „Bezeichnung“ und „Vertragspartner“. Gibt es schon einen Vertrag mit gleichem Vertragspartner und gleicher Vertragsnummer (ohne Nummer: gleicher Bezeichnung), wird er aktualisiert; leere Zellen lassen bestehende Werte unverändert. Unbekannte Vertragsarten werden angelegt. Datum als TT.MM.JJJJ oder JJJJ-MM-TT; Zeitraum: Monat, Quartal, Jahr, einmalig; Einheit: Tage, Wochen, Monate; Betreuung: IT-Dienstleister, Firma selbst oder Name eines Dienstleisters.' => '« Désignation » et « Partenaire contractuel » sont obligatoires. Si un contrat avec le même partenaire et le même n° de contrat (sans n° : la même désignation) existe déjà, il est mis à jour ; les cellules vides ne modifient pas les valeurs existantes. Les types de contrat inconnus sont créés. Dates au format JJ.MM.AAAA ou AAAA-MM-JJ ; période : mois, trimestre, année, unique ; unité : jours, semaines, mois ; gestion : prestataire informatique, l’entreprise elle-même ou nom d’un prestataire.',
    'Aktuelle Verträge als Vorlage exportieren' => 'Exporter les contrats actuels comme modèle',
    'Die Kostenübersicht sehen nur Benutzer mit dem Recht „Kosten sehen“.' => 'Seuls les utilisateurs ayant le droit « Voir les coûts » voient l’aperçu des coûts.',
