    'pro Jahr (bei heutigen Preisen)' => 'par an (aux prix actuels)',
    'nächste 12 Monate (mit Änderungen)' => '12 prochains mois (avec changements)',
    'Alle Beträge wie eingetragen (z. B. netto). Vierteljährliche und jährliche Kosten sind auf den Monat umgerechnet.' => 'Tous les montants tels que saisis (p. ex. HT). Les coûts trimestriels et annuels sont convertis au mois.',
    'Lizenzen aus dem Inventar sind enthalten.' => 'Les licences de l’inventaire sont incluses.',
    'Nach Vertragsart' => 'Par type de contrat',
    'Nach Anbieter' => 'Par fournisseur',
    'Hochrechnung der nächsten 12 Monate' => 'Projection sur les 12 prochains mois',
    'Berücksichtigt Preisänderungen, gekündigte und auslaufende Verträge sowie den Vertragsbeginn. Einmalige Kosten zählen im Monat des Beginns.' => 'Tient compte des changements de prix, des contrats résiliés ou arrivant à échéance et du début du contrat. Les coûts uniques comptent le mois du début.',
    'Monat' => 'Mois',
    'Einmalige Kosten' => 'Coûts uniques',
    'Ausblick: Fristen und Preisänderungen' => 'Perspectives : échéances et changements de prix',
    'Keine laufenden Kosten erfasst.' => 'Aucun coût courant saisi.',
    'Anteil' => 'Part',
    'Schnittstelle (API)' => 'Interface (API)',
    'Verträge aus anderen Programmen lesen, anlegen und ändern sowie Fristen abfragen. Jeder Schlüssel gilt nur für diese Firma.' => 'Lire, créer et modifier des contrats depuis d’autres programmes et consulter les échéances. Chaque clé ne vaut que pour cette entreprise.',
    'Neuer Schlüssel (nur jetzt sichtbar):' => 'Nouvelle clé (visible uniquement maintenant) :',
    'lesen und schreiben' => 'lecture et écriture',
    'nur lesen' => 'lecture seule',
    'mit Kosten' => 'avec les coûts',
    'z. B. Buchhaltung, CRM' => 'p. ex. comptabilité, CRM',
    'darf Verträge anlegen und ändern' => 'peut créer et modifier des contrats',
    'darf Kosten lesen und schreiben' => 'peut lire et écrire les coûts',
    'Verträge auflisten (status: laufend, alle, aktiv, gekuendigt, …)' => 'Lister les contrats (status : laufend, alle, aktiv, gekuendigt, …)',
    'einen Vertrag abrufen, mit Preishistorie (bei Kostenrecht)' => 'obtenir un contrat, avec l’historique des prix (avec droit sur les coûts)',
    'Vertrag anlegen; mit gleichem Vertragspartner und gleicher Vertragsnummer wird aktualisiert. Auch eine Liste ist möglich.' => 'Créer un contrat ; avec le même partenaire et le même n° de contrat, il est mis à jour. Une liste est aussi possible.',
    'Fristen und Preisänderungen der nächsten Monate' => 'Échéances et changements de prix des prochains mois',
    'Vertragsarten der Firma' => 'Types de contrat de l’entreprise',
    'Felder:' => 'Champs :',
    'Datum als JJJJ-MM-TT, Kosten als Zahl (z. B. 49.9).' => 'Dates au format AAAA-MM-JJ, coûts sous forme de nombre (p. ex. 49.9).',
    'Die App „Verträge & Laufzeiten“ ist für diese Firma nicht freigeschaltet.' => 'L’application « Contrats & échéances » n’est pas activée pour cette entreprise.',
    'Vertrag nicht gefunden.' => 'Contrat introuvable.',
    'Feld „{x}“ muss Text oder Zahl sein.' => 'Le champ « {x} » doit être du texte ou un nombre.',
    'Höchstens 1000 Verträge pro Aufruf.' => '1000 contrats maximum par appel.',
    'Dieser API-Schlüssel gilt nur für Verträge.' => 'Cette clé API ne vaut que pour les contrats.',
    'Für Verträge wird ein eigener API-Schlüssel aus der App „Verträge & Laufzeiten“ benötigt.' => 'Les contrats nécessitent une clé API distincte de l’application « Contrats & échéances ».',
    'Einheit der Kündigungsfrist' => 'Unité du délai de résiliation',
    // Verträge, Stufe 7: PDF auslesen, Texterkennung, Vorjahresvergleich
    'Aus PDF erfassen' => 'Saisir depuis un PDF',
    'Vorausgefüllt aus „{x}“ ({n} Angaben gefunden). Bitte alles prüfen – die PDF wird beim Anlegen als Dokument „Vertrag“ angehängt.' => 'Prérempli à partir de « {x} » ({n} informations trouvées). Veuillez tout vérifier – le PDF sera joint comme document « Contrat » lors de la création.',
    'Daten auslesen' => 'Lire les données',
    'Vorjahresvergleich {a} – {b}' => 'Comparaison avec l’année précédente {a} – {b}',
    '(mit Hochrechnung)' => '(avec projection)',
    'Veränderung' => 'Variation',
    'Berechnet aus den eingetragenen Verträgen und Preisen (keine Buchhaltungsdaten). Beendete Verträge zählen bis zu ihrem Ende; Verträge ohne Beginn zählen, als ob sie schon im Vorjahr liefen. Monate ab heute sind hochgerechnet.' => 'Calculé à partir des contrats et prix saisis (pas de données comptables). Les contrats terminés comptent jusqu’à leur fin ; les contrats sans date de début comptent comme s’ils couraient déjà l’année précédente. Les mois à partir d’aujourd’hui sont projetés.',
    'Keine Kosten in diesem Zeitraum.' => 'Aucun coût sur cette période.',
    'Nach Monat' => 'Par mois',
    'Hochrechnung' => 'projection',
    'automatisch' => 'automatique',
    'Die Texterkennung ist für diese Firma nicht eingeschaltet.' => 'La reconnaissance de texte n’est pas activée pour cette entreprise.',
    'Die Texterkennung ist nicht erreichbar: {x}' => 'La reconnaissance de texte est injoignable : {x}',
    'Der API-Schlüssel für die Texterkennung wurde abgelehnt.' => 'La clé API de la reconnaissance de texte a été refusée.',
    'Die Texterkennung meldet zu viele Anfragen (Kontingent erschöpft). Bitte später erneut versuchen.' => 'La reconnaissance de texte signale trop de requêtes (quota épuisé). Veuillez réessayer plus tard.',
    'Die Texterkennung hat einen Fehler gemeldet (HTTP {n}).' => 'La reconnaissance de texte a signalé une erreur (HTTP {n}).',
    'Die Texterkennung ist ausgeschaltet, der API-Schlüssel wurde gelöscht.' => 'La reconnaissance de texte est désactivée, la clé API a été supprimée.',
    'Bitte den API-Schlüssel von Mistral eintragen.' => 'Veuillez saisir la clé API de Mistral.',
    'Bitte beide Bestätigungen setzen. Ohne sie bleibt die Texterkennung aus.' => 'Veuillez cocher les deux confirmations. Sans elles, la reconnaissance de texte reste désactivée.',
    'Die Texterkennung über Mistral OCR ist eingeschaltet. Vor jeder Übertragung wird nachgefragt.' => 'La reconnaissance de texte via Mistral OCR est activée. Une confirmation est demandée avant chaque transfert.',
    'Daten aus PDF auslesen' => 'Lire les données d’un PDF',
    'Standard: Der Server liest den Text der PDF selbst und sucht Daten, Fristen und Beträge. Es werden keine Daten an Dritte übertragen und es entstehen keine Kosten.' => 'Par défaut : le serveur lit lui-même le texte du PDF et recherche dates, délais et montants. Aucune donnée n’est transmise à des tiers et cela ne coûte rien.',
    'Gescannte PDFs enthalten nur Bilder. Für sie kann die Firma die Texterkennung „Mistral OCR“ von Mistral AI (Paris, Verarbeitung in der EU) mit einem eigenen Konto einschalten. Dann wird die jeweilige PDF zur Texterkennung an Mistral übertragen – nur nach Rückfrage bei jedem Dokument.' => 'Les PDF numérisés ne contiennent que des images. Pour eux, l’entreprise peut activer la reconnaissance de texte « Mistral OCR » de Mistral AI (Paris, traitement dans l’UE) avec son propre compte. Le PDF est alors transmis à Mistral – uniquement après confirmation pour chaque document.',
    'eingeschaltet' => 'activée',
    'bestätigt von {n} am {d}' => 'confirmé par {n} le {d}',
    'Ein- und ausschalten kann nur ein Firmen-Admin der Firma selbst.' => 'Seul un administrateur de l’entreprise elle-même peut l’activer ou la désactiver.',
    'API-Schlüssel von Mistral (console.mistral.ai)' => 'Clé API Mistral (console.mistral.ai)',
    'Wir haben den Auftragsverarbeitungsvertrag (DPA) von Mistral AI für unser Konto abgeschlossen.' => 'Nous avons conclu l’accord de traitement des données (DPA) de Mistral AI pour notre compte.',
    'Wir haben geprüft, dass Mistral die übertragenen Dokumente in unserem Tarif nicht zum Training verwendet und nicht dauerhaft speichert.' => 'Nous avons vérifié que, dans notre offre, Mistral n’utilise pas les documents transmis pour l’entraînement et ne les conserve pas durablement.',
    'Kosten und Mengengrenzen richten sich nach Ihrem Mistral-Konto. Der Schlüssel wird verschlüsselt gespeichert und ist nicht in der Datensicherung enthalten.' => 'Les coûts et limites dépendent de votre compte Mistral. La clé est stockée chiffrée et n’est pas incluse dans la sauvegarde.',
    'Texterkennung einschalten' => 'Activer la reconnaissance de texte',
    'Texterkennung ausschalten und API-Schlüssel löschen?' => 'Désactiver la reconnaissance de texte et supprimer la clé API ?',
    'Ausschalten' => 'Désactiver',
    'Die hochgeladene Datei ist nicht mehr vorhanden. Bitte erneut hochladen.' => 'Le fichier téléversé n’est plus disponible. Veuillez le téléverser à nouveau.',
    'Bitte eine PDF-Datei hochladen.' => 'Veuillez téléverser un fichier PDF.',
    'Bitte bestätigen, dass die PDF an Mistral AI übertragen werden darf.' => 'Veuillez confirmer que le PDF peut être transmis à Mistral AI.',
    'Der Text wurde erkannt.' => 'Le texte a été reconnu.',
    'Bitte mindestens ein Feld zum Übernehmen auswählen.' => 'Veuillez sélectionner au moins un champ à reprendre.',
    'Die ausgewählten Angaben wurden übernommen.' => 'Les informations sélectionnées ont été reprises.',
    'Vertrag aus PDF erfassen' => 'Saisir un contrat depuis un PDF',
    'Laden Sie einen Vertrag, eine Auftrags- oder Vertragsbestätigung als PDF hoch. Das Portal sucht Vertragspartner, Nummern, Laufzeit, Kündigungsfrist und Kosten und füllt damit das Formular vor. Sie prüfen alles, bevor der Vertrag angelegt wird.' => 'Téléversez un contrat, une confirmation de commande ou de contrat au format PDF. Le portail recherche le prestataire, les numéros, la durée, le préavis et les coûts et préremplit le formulaire. Vous vérifiez tout avant la création du contrat.',
    'PDF-Datei (höchstens 10 MB)' => 'Fichier PDF (10 Mo max.)',
    'Hochladen und auslesen' => 'Téléverser et lire',
    'Daten aus „{x}“' => 'Données de « {x} »',
    'Text direkt aus der PDF gelesen – ohne KI, ohne Übertragung an Dritte.' => 'Texte lu directement dans le PDF – sans IA, sans transmission à des tiers.',
    'Text per Texterkennung „Mistral OCR“ (Mistral AI, EU) erkannt.' => 'Texte reconnu via « Mistral OCR » (Mistral AI, UE).',
    'In dieser PDF wurde kein Text gefunden. Vermutlich ist sie gescannt (nur Bild).' => 'Aucun texte n’a été trouvé dans ce PDF. Il est probablement numérisé (image uniquement).',
    'Texterkennung mit Mistral OCR' => 'Reconnaissance de texte avec Mistral OCR',
    'Dienst: Mistral AI SAS, Paris (Verarbeitung in der EU). Die komplette PDF „{x}“ wird dazu an Mistral übertragen.' => 'Service : Mistral AI SAS, Paris (traitement dans l’UE). Le PDF complet « {x} » est transmis à Mistral à cet effet.',
    'Ich bin einverstanden, dass diese PDF zur Texterkennung an Mistral AI übertragen wird.' => 'J’accepte que ce PDF soit transmis à Mistral AI pour la reconnaissance de texte.',
    'Text erkennen lassen' => 'Reconnaître le texte',
    'Stattdessen per Texterkennung lesen' => 'Lire plutôt avec la reconnaissance de texte',
    'Für gescannte PDFs kann ein Firmen-Admin in den Einstellungen die Texterkennung „Mistral OCR“ einschalten. Ohne sie bitte die Angaben von Hand eintragen.' => 'Pour les PDF numérisés, un administrateur de l’entreprise peut activer la reconnaissance « Mistral OCR » dans les paramètres. Sinon, veuillez saisir les informations à la main.',
    'Gefundene Angaben' => 'Informations trouvées',
    'Es wurden keine passenden Angaben gefunden.' => 'Aucune information correspondante n’a été trouvée.',
    'Vorschläge ohne Gewähr: Bitte mit dem Dokument vergleichen. Leere Felder sind vorausgewählt, abweichende Werte nicht.' => 'Suggestions sans garantie : veuillez comparer avec le document. Les champs vides sont présélectionnés, les valeurs différentes non.',
    'Bisher' => 'Actuel',
    'Gefunden' => 'Trouvé',
    'Fundstelle' => 'Passage',
    'übernehmen' => 'reprendre',
    'stimmt überein' => 'identique',
    'abweichend' => 'différent',
    'Ausgewählte übernehmen' => 'Reprendre la sélection',
    'Es wurden keine passenden Angaben gefunden. Sie können den Vertrag trotzdem anlegen, die PDF wird angehängt.' => 'Aucune information correspondante n’a été trouvée. Vous pouvez tout de même créer le contrat ; le PDF sera joint.',
    'Weiter zum Formular' => 'Continuer vers le formulaire',
    'Im Formular sind die Angaben vorausgefüllt. Beim Anlegen wird die PDF als Dokument „Vertrag“ gespeichert.' => 'Le formulaire est prérempli. Lors de la création, le PDF est enregistré comme document « Contrat ».',
    'Gelesenen Text anzeigen' => 'Afficher le texte lu',
    'Datenschutz: Die PDF wird auf diesem Server ausgelesen, ohne KI und ohne Übertragung an Dritte.' => 'Protection des données : le PDF est lu sur ce serveur, sans IA et sans transmission à des tiers.',
    'Nur wenn Sie bei einer gescannten PDF ausdrücklich „Text erkennen lassen“ wählen, wird sie an Mistral AI (EU) übertragen.' => 'Ce n’est que si vous choisissez expressément « Reconnaître le texte » pour un PDF numérisé qu’il est transmis à Mistral AI (UE).',
    'Aus Dokument übernommen' => 'Repris du document',
    'Text per Mistral OCR erkannt' => 'Texte reconnu via Mistral OCR',
    'Aus PDF erfasst' => 'Saisi depuis un PDF',
    'Tag' => 'jour',
    'Woche' => 'semaine',
    'API-Schlüssel erzeugen und löschen können nur die Firmen-Admins der Firma selbst.' => 'Seuls les administrateurs de l’entreprise elle-même peuvent créer et supprimer des clés API.',
    'Zeile {n}: „{x}“ passt zu mehreren Lizenzen ohne Vertragsnummer. Bitte Vertragsnummer oder Lieferant ergänzen.' => 'Ligne {n} : « {x} » correspond à plusieurs licences sans numéro de contrat. Veuillez ajouter le numéro de contrat ou le fournisseur.',
    'Das Wiki dieser Firma ist nur intern sichtbar. Die Firma kann die Einsicht für den IT-Dienstleister unter Einstellungen einschalten.' => 'Le wiki de cette entreprise est uniquement interne. L’entreprise peut autoriser l’accès à son prestataire informatique sous Paramètres.',
    'Sie haben keinen Zugriff auf diesen Bereich. Die Rechte vergeben die Administratoren Ihrer Firma.' => 'Vous n’avez pas accès à cet espace. Les droits sont attribués par les administrateurs de votre entreprise.',
    'Unterseiten ein- oder ausklappen' => 'Déplier ou replier les sous-pages',
    'Seitenbaum' => 'Arborescence des pages',
    'Noch keine Seiten.' => 'Aucune page pour l’instant.',
    '+ Seite' => '+ Page',
    'Inhalt' => 'Sommaire',
    'Die Seite hat noch keine Überschriften.' => 'Cette page n’a pas encore de titres.',
    'Bereiche' => 'Espaces',
    'Wiki durchsuchen …' => 'Rechercher dans le wiki …',
    'Wiki durchsuchen' => 'Rechercher dans le wiki',
    'Dokumente & Anleitungen' => 'Documents et guides',
    '+ Bereich' => '+ Espace',
    'Willkommen im Wiki' => 'Bienvenue dans le wiki',
    'Legen Sie Bereiche an, zum Beispiel einen je Abteilung oder für „IT“, „Richtlinien“ und „Notfall“. In jedem Bereich entsteht ein Seitenbaum mit Anleitungen und Handbüchern.' => 'Créez des espaces, par exemple un par service ou pour « IT », « Directives » et « Urgence ». Chaque espace contient une arborescence de guides et de manuels.',
    'Bereiche aus den Abteilungen anlegen' => 'Créer des espaces à partir des services',
    'Es gibt noch keine Bereiche, auf die Sie Zugriff haben.' => 'Il n’y a pas encore d’espace auquel vous avez accès.',
    '1 Seite' => '1 page',
    '{n} Seiten' => '{n} pages',
