    'Diese Seite wirklich löschen? Das lässt sich nicht rückgängig machen.' => 'Vraiment supprimer cette page ? Cette action est irréversible.',
    'Bitte zuerst die Unterseiten verschieben oder löschen.' => 'Veuillez d’abord déplacer ou supprimer les sous-pages.',
    'Seite löschen' => 'Supprimer la page',
    'Die Seite ist zu groß (höchstens {n} MB inklusive Bilder). Bitte Bilder verkleinern oder auf mehrere Seiten verteilen.' => 'La page est trop volumineuse ({n} Mo maximum, images comprises). Veuillez réduire les images ou répartir le contenu sur plusieurs pages.',
    'Die Seite wurde gespeichert.' => 'La page a été enregistrée.',
