    'Rückgängig (Strg+Z)' => 'Annuler (Ctrl+Z)',
    'Wiederholen (Strg+Y)' => 'Rétablir (Ctrl+Y)',
    'Tipp: Bilder lassen sich auch per Kopieren und Einfügen oder Ziehen einfügen. Strg+S speichert.' => 'Astuce : vous pouvez aussi coller ou glisser des images. Ctrl+S enregistre.',
    '{n} Bereiche wurden angelegt. Die jeweilige Abteilung darf ihren Bereich bearbeiten.' => '{n} espaces ont été créés. Chaque service peut modifier son propre espace.',
    'Es gibt keine Abteilungen ohne eigenen Bereich. Abteilungen pflegen Sie unter On- & Offboarding → Abteilungen & Positionen.' => 'Il n’y a aucun service sans espace propre. Les services se gèrent sous On- & Offboarding → Services & postes.',
    'Die Seite wurde gelöscht.' => 'La page a été supprimée.',
    'Bereiche pflegen die Administratoren der Firma.' => 'Les espaces sont gérés par les administrateurs de l’entreprise.',
    'Der Bereich enthält noch Seiten. Bitte zuerst die Seiten löschen.' => 'L’espace contient encore des pages. Veuillez d’abord supprimer les pages.',
    'Der Bereich wurde gelöscht.' => 'L’espace a été supprimé.',
    'Der Bereich wurde gespeichert.' => 'L’espace a été enregistré.',
    'Neuer Bereich' => 'Nouvel espace',
    'z. B. IT, Personal, Richtlinien, Notfall' => 'p. ex. IT, RH, Directives, Urgence',
    'Symbol (Emoji)' => 'Icône (emoji)',
    'Wer darf was?' => 'Qui peut faire quoi ?',
    'Alle Mitarbeiter der Firma dürfen diesen Bereich lesen' => 'Tous les collaborateurs de l’entreprise peuvent lire cet espace',
    'Gruppe (Abteilung)' => 'Groupe (service)',
    'Es gibt noch keine Abteilungen. Abteilungen pflegen Sie unter On- & Offboarding → Abteilungen & Positionen.' => 'Il n’y a pas encore de services. Les services se gèrent sous On- & Offboarding → Services & postes.',
    'Firmen-Administratoren dürfen immer alles. Der IT-Dienstleister sieht das Wiki nur, wenn Sie das unter Einstellungen erlauben.' => 'Les administrateurs de l’entreprise peuvent toujours tout faire. Le prestataire informatique ne voit le wiki que si vous l’autorisez sous Paramètres.',
    'Diesen Bereich wirklich löschen?' => 'Vraiment supprimer cet espace ?',
    'Bereich löschen' => 'Supprimer l’espace',
    'Nur leere Bereiche lassen sich löschen.' => 'Seuls les espaces vides peuvent être supprimés.',
    'Unser IT-Dienstleister darf unser Wiki sehen und pflegen' => 'Notre prestataire informatique peut consulter et gérer notre wiki',
    'Ohne diese Einsicht sieht der IT-Dienstleister keine Bereiche und Seiten. Ihre eigenen Rechte über Gruppen gelten unabhängig davon.' => 'Sans cet accès, le prestataire informatique ne voit ni espaces ni pages. Vos propres droits par groupe s’appliquent indépendamment.',
    'Bereiche aus den Abteilungen' => 'Espaces à partir des services',
    'Legt für jede Abteilung ohne eigenen Bereich einen Bereich an. Die Abteilung darf ihn bearbeiten, alle anderen sehen ihn nicht, bis Sie das ändern.' => 'Crée un espace pour chaque service qui n’en a pas encore. Le service peut le modifier ; personne d’autre ne le voit tant que vous ne le changez pas.',
    'Suche' => 'Recherche',
