    'Sie erhalten diese Nachricht, weil Sie die Seite beobachten. Abbestellen: auf der Seite „Nicht mehr beobachten“ wählen.' => 'Vous recevez ce message parce que vous suivez la page. Pour vous désabonner, choisissez « Ne plus suivre » sur la page.',
