    'Diese Seiten sehen alle Firmen, für die „Dokumente & Anleitungen“ freigeschaltet ist. Entwürfe sehen nur Sie und Ihre Admins. Firmen können eine Seite in ihr eigenes Wiki kopieren und anpassen.' => 'Ces pages sont visibles par toutes les entreprises pour lesquelles « Documents et guides » est activé. Seuls vous et vos administrateurs voyez les brouillons. Les entreprises peuvent copier une page dans leur propre wiki et l’adapter.',
    'überfällig seit {d}' => 'en retard depuis le {d}',
    'fällig am {d}' => 'à faire le {d}',
    'Entwürfe' => 'Brouillons',
