    'In unser Wiki kopieren, Bereich:' => 'Copier dans notre wiki, espace :',
    'Kopieren' => 'Copier',
    'Die Kopie entsteht als Entwurf und lässt sich dann anpassen. Spätere Änderungen Ihres IT-Dienstleisters übernimmt sie nicht automatisch.' => 'La copie est créée comme brouillon que vous pouvez ensuite adapter. Les modifications ultérieures de votre prestataire informatique n’y sont pas reprises automatiquement.',
