    'Tresor' => 'Coffre-fort',
    'Der Tresor dieser Firma ist für Ihr Konto nicht freigegeben. Nur die Firma selbst kann einzelne Ordner für Sie freigeben.' => 'Le coffre-fort de cette entreprise n’est pas partagé avec votre compte. Seule l’entreprise peut vous ouvrir certains dossiers.',
    'Der Tresor braucht JavaScript: Ver- und Entschlüsselung laufen ausschließlich in Ihrem Browser.' => 'Le coffre-fort nécessite JavaScript : le chiffrement et le déchiffrement ont lieu uniquement dans votre navigateur.',
