    'Unbekannter Fehler.' => 'Erreur inconnue.',
    'Ordner „{n}“ wurde neu verschlüsselt.' => 'Le dossier « {n} » a été rechiffré.',
    'Ordner „{n}“ wurde für {x} weitere Zugänge freigeschaltet.' => 'Le dossier « {n} » a été ouvert à {x} accès supplémentaires.',
    'Der Schlüssel für Ordner „{n}“ ließ sich nicht entschlüsseln.' => 'La clé du dossier « {n} » n’a pas pu être déchiffrée.',
    'Der Tresor wurde nach 1 Minute ohne Aktivität gesperrt.' => 'Le coffre-fort a été verrouillé après 1 minute d’inactivité.',
    'Der Tresor wurde nach {n} Minuten ohne Aktivität gesperrt.' => 'Le coffre-fort a été verrouillé après {n} minutes d’inactivité.',
    'Ihr Browser unterstützt die nötige Verschlüsselung nicht (Web Crypto). Bitte nutzen Sie einen aktuellen Browser über HTTPS.' => 'Votre navigateur ne prend pas en charge le chiffrement nécessaire (Web Crypto). Veuillez utiliser un navigateur récent via HTTPS.',
    'Das Tresor-Passwort muss mindestens 12 Zeichen lang sein.' => 'Le mot de passe du coffre-fort doit comporter au moins 12 caractères.',
    'Ihr persönliches Notfallkit' => 'Votre kit d’urgence personnel',
    'Mit diesem Notfallkit setzen Sie ein neues Tresor-Passwort, falls Sie es vergessen. Wer das Kit hat, kann zusammen mit Ihrer Portal-Anmeldung Ihren Tresor öffnen – bewahren Sie es sicher auf.' => 'Ce kit d’urgence vous permet de définir un nouveau mot de passe si vous l’oubliez. Quiconque possède le kit et vos identifiants du portail peut ouvrir votre coffre-fort – conservez-le en lieu sûr.',
    'Ihr Tresor-Zugang ist eingerichtet.' => 'Votre accès au coffre-fort est configuré.',
    'Der Tresor verschlüsselt Zugangsdaten direkt in Ihrem Browser. Weder der Server noch Ihr IT-Dienstleister können sie lesen.' => 'Le coffre-fort chiffre les identifiants directement dans votre navigateur. Ni le serveur ni votre prestataire informatique ne peuvent les lire.',
    'Legen Sie dafür ein eigenes Tresor-Passwort fest. Es ist unabhängig von Ihrem Portal-Passwort und wird nirgends gespeichert.' => 'Définissez pour cela un mot de passe propre au coffre-fort. Il est indépendant de votre mot de passe du portail et n’est enregistré nulle part.',
    'Tresor-Passwort (mindestens 12 Zeichen)' => 'Mot de passe du coffre-fort (au moins 12 caractères)',
    'Tresor-Passwort wiederholen' => 'Répéter le mot de passe du coffre-fort',
    'Wichtig: Vergessen Sie das Tresor-Passwort und verlieren das Notfallkit, kann niemand Ihren Zugang wiederherstellen. Ihre Firma kann Ihnen dann nur einen neuen Zugang einrichten und die Ordner neu freigeben.' => 'Important : si vous oubliez le mot de passe et perdez le kit d’urgence, personne ne pourra restaurer votre accès. Votre entreprise pourra seulement vous créer un nouvel accès et vous rouvrir les dossiers.',
    'Tresor-Zugang einrichten' => 'Configurer l’accès au coffre-fort',
    'Tresor einrichten' => 'Configurer le coffre-fort',
    'Bitte warten …' => 'Veuillez patienter …',
    'Notfallkit – Passwort-Tresor' => 'Kit d’urgence – coffre-fort de mots de passe',
    'Aufbewahren: ausgedruckt an einem sicheren Ort (z. B. Tresor oder Safe), nicht als Datei auf demselben Rechner und nicht per E-Mail versenden.' => 'À conserver imprimé dans un lieu sûr (p. ex. un coffre), pas sous forme de fichier sur le même ordinateur, et ne pas l’envoyer par e-mail.',
    'Als Textdatei speichern' => 'Enregistrer en fichier texte',
    'Ich habe das Notfallkit gedruckt oder sicher abgelegt.' => 'J’ai imprimé ou rangé en lieu sûr le kit d’urgence.',
