    'Tresor entsperren' => 'Déverrouiller le coffre-fort',
    'Das Notfallkit ist unvollständig. Bitte alle Zeichen eingeben.' => 'Le kit d’urgence est incomplet. Veuillez saisir tous les caractères.',
    'Das Notfallkit passt nicht zu Ihrem Tresor-Zugang.' => 'Le kit d’urgence ne correspond pas à votre accès au coffre-fort.',
    'Ihr neues Tresor-Passwort gilt ab sofort. Das Notfallkit bleibt gültig.' => 'Votre nouveau mot de passe est valable immédiatement. Le kit d’urgence reste valable.',
    'Geben Sie Ihr persönliches Notfallkit ein (beginnt mit KP1-) und legen Sie ein neues Tresor-Passwort fest.' => 'Saisissez votre kit d’urgence personnel (commence par KP1-) et définissez un nouveau mot de passe.',
    'Notfallkit' => 'Kit d’urgence',
    'Neues Tresor-Passwort (mindestens 12 Zeichen)' => 'Nouveau mot de passe du coffre-fort (au moins 12 caractères)',
    'Neues Tresor-Passwort wiederholen' => 'Répéter le nouveau mot de passe',
    'Neues Passwort setzen' => 'Définir le nouveau mot de passe',
    'Kein Notfallkit mehr? Dann kann ein Administrator Ihrer Firma Ihren Tresor-Zugang zurücksetzen. Danach richten Sie ihn neu ein und bekommen die Ordner erneut freigegeben.' => 'Plus de kit d’urgence ? Un administrateur de votre entreprise peut alors réinitialiser votre accès. Vous le configurez ensuite à nouveau et les dossiers vous sont rouverts.',
    'Tresor-Passwort vergessen' => 'Mot de passe du coffre-fort oublié',
    'Tresor noch nicht aktiviert' => 'Coffre-fort pas encore activé',
    'Ihr Tresor-Zugang ist eingerichtet. Sobald ein Administrator Ihrer Firma den Tresor aktiviert und Ihnen Ordner freigibt, sehen Sie hier die Zugangsdaten.' => 'Votre accès est configuré. Dès qu’un administrateur de votre entreprise active le coffre-fort et vous ouvre des dossiers, vous verrez les identifiants ici.',
    'Tresor für die Firma aktivieren' => 'Activer le coffre-fort pour l’entreprise',
    'Beim Aktivieren entsteht der Firmen-Notfallschlüssel. Jeder Ordner wird zusätzlich für ihn verschlüsselt. Mit dem ausgedruckten Firmen-Notfallkit kann ein Administrator alle Ordner wieder öffnen, auch wenn alle Mitglieder ihren Zugang verloren haben.' => 'L’activation crée la clé d’urgence de l’entreprise. Chaque dossier est en plus chiffré pour elle. Avec le kit d’urgence imprimé, un administrateur peut rouvrir tous les dossiers même si tous les membres ont perdu leur accès.',
    'Das Firmen-Notfallkit ist der Generalschlüssel des Tresors. Drucken Sie es aus und bewahren Sie es bei der Geschäftsführung im Safe auf. Es wird nirgends gespeichert und kann nicht erneut angezeigt werden.' => 'Le kit d’urgence de l’entreprise est la clé maîtresse du coffre-fort. Imprimez-le et conservez-le dans le coffre de la direction. Il n’est enregistré nulle part et ne peut pas être réaffiché.',
    'Firmen-Notfallkit' => 'Kit d’urgence de l’entreprise',
    'Mit diesem Kit öffnet ein Administrator der Firma unter „Notfallzugriff“ alle Ordner des Tresors.' => 'Avec ce kit, un administrateur de l’entreprise ouvre tous les dossiers du coffre-fort sous « Accès d’urgence ».',
    'Der Tresor ist aktiviert. Legen Sie jetzt Ordner an und vergeben Sie Rechte.' => 'Le coffre-fort est activé. Créez maintenant des dossiers et attribuez les droits.',
    'Firmen-Notfallschlüssel erzeugen und Tresor aktivieren' => 'Créer la clé d’urgence et activer le coffre-fort',
    'Entsperrt – sperrt nach 1 Minute ohne Aktivität' => 'Déverrouillé – se verrouille après 1 minute d’inactivité',
    'Entsperrt – sperrt nach {n} Minuten ohne Aktivität' => 'Déverrouillé – se verrouille après {n} minutes d’inactivité',
    '+ Ordner' => '+ Dossier',
    'Notfallzugriff' => 'Accès d’urgence',
    'Mein Zugang' => 'Mon accès',
    'Der Tresor ist gesperrt.' => 'Le coffre-fort est verrouillé.',
    'Sperren' => 'Verrouiller',
    'Noch keine Ordner. Legen Sie mit „+ Ordner“ den ersten an, zum Beispiel „IT“, „Geschäftsführung“ oder „WLAN“.' => 'Pas encore de dossiers. Créez le premier avec « + Dossier », par exemple « IT », « Direction » ou « Wi-Fi ».',
    'Für Sie ist noch kein Ordner freigegeben.' => 'Aucun dossier ne vous a encore été ouvert.',
    '+ Eintrag' => '+ Entrée',
    'Ordner bearbeiten' => 'Modifier le dossier',
    'Dieser Ordner ist für Ihr Konto noch nicht freigeschaltet. Sobald ein Mitglied den Tresor öffnet, geschieht das automatisch – oder Sie nutzen den Notfallzugriff.' => 'Ce dossier n’est pas encore ouvert pour votre compte. Cela se fait automatiquement dès qu’un membre ouvre le coffre-fort – ou utilisez l’accès d’urgence.',
    'Dieser Ordner ist für Ihr Konto noch nicht freigeschaltet. Sobald jemand mit Zugriff den Tresor öffnet, geschieht das automatisch.' => 'Ce dossier n’est pas encore ouvert pour votre compte. Cela se fait automatiquement dès qu’une personne ayant accès ouvre le coffre-fort.',
    'Noch ohne Tresor-Zugang (bekommen den Ordner automatisch, sobald sie ihn einrichten): {n}' => 'Sans accès au coffre-fort pour l’instant (recevront le dossier automatiquement après configuration) : {n}',
    'Einträge filtern …' => 'Filtrer les entrées …',
    'Einträge filtern' => 'Filtrer les entrées',
    'Keine Treffer.' => 'Aucun résultat.',
    'Noch keine Einträge in diesem Ordner.' => 'Pas encore d’entrées dans ce dossier.',
    'Ändern bis' => 'À changer avant',
    'Kopieren wird von diesem Browser nicht unterstützt.' => 'La copie n’est pas prise en charge par ce navigateur.',
    'Kopiert. Die Zwischenablage wird in 30 Sekunden geleert.' => 'Copié. Le presse-papiers sera vidé dans 30 secondes.',
    'Kopieren nicht möglich.' => 'Copie impossible.',
    'Öffnen' => 'Ouvrir',
    'Verbergen' => 'Masquer',
    'Geheime Felder zeigen' => 'Afficher les champs secrets',
    'Der Eintrag ließ sich nicht entschlüsseln.' => 'L’entrée n’a pas pu être déchiffrée.',
    'Ordner „{n}“ · geändert {d} von {u}' => 'Dossier « {n} » · modifié le {d} par {u}',
    'Jedes Anzeigen und Kopieren wird protokolliert.' => 'Chaque affichage et chaque copie sont journalisés.',
    'Diesen Eintrag endgültig löschen?' => 'Supprimer définitivement cette entrée ?',
    'Der Eintrag wurde gelöscht.' => 'L’entrée a été supprimée.',
    'Zeigen' => 'Afficher',
    'Der Eintrag wurde verschlüsselt gespeichert.' => 'L’entrée a été enregistrée chiffrée.',
    'Ändern bis (optional)' => 'À changer avant (facultatif)',
    'Titel, Art und „Ändern bis“ sind für die Liste unverschlüsselt gespeichert. Alle anderen Felder werden in Ihrem Browser verschlüsselt.' => 'Le titre, le type et « À changer avant » sont stockés en clair pour la liste. Tous les autres champs sont chiffrés dans votre navigateur.',
    'Eintrag bearbeiten' => 'Modifier l’entrée',
    'Neuer Eintrag' => 'Nouvelle entrée',
    'noch ohne Tresor-Zugang' => 'pas encore d’accès au coffre-fort',
    'Der Ordner wurde gespeichert. Neue Mitglieder werden automatisch freigeschaltet.' => 'Le dossier a été enregistré. Les nouveaux membres sont ouverts automatiquement.',
    'Keine Abteilungen angelegt.' => 'Aucun service créé.',
    'Rechte für einzelne Personen' => 'Droits pour des personnes individuelles',
    'Ihr IT-Dienstleister bekommt nur Zugriff, wenn Sie ihn hier ausdrücklich eintragen. Administratoren der Firma haben immer Zugriff.' => 'Votre prestataire informatique n’a accès que si vous l’ajoutez explicitement ici. Les administrateurs de l’entreprise ont toujours accès.',
    'Wer ein Recht verliert, verliert sofort den Zugriff. Beim nächsten Öffnen durch eine Person mit Bearbeiten-Recht wird der Ordner automatisch neu verschlüsselt.' => 'Toute personne qui perd un droit perd immédiatement l’accès. À la prochaine ouverture par une personne autorisée à modifier, le dossier est automatiquement rechiffré.',
    'Der Ordner wird mit allen Einträgen endgültig gelöscht. Zum Bestätigen den Namen des Ordners eingeben:' => 'Le dossier sera supprimé définitivement avec toutes ses entrées. Saisissez le nom du dossier pour confirmer :',
    'Der Name stimmt nicht. Nichts wurde gelöscht.' => 'Le nom ne correspond pas. Rien n’a été supprimé.',
    'Das Firmen-Notfallkit passt nicht.' => 'Le kit d’urgence de l’entreprise ne correspond pas.',
    'Notfallzugriff: {n} Ordner wurden für Ihr Konto freigeschaltet.' => 'Accès d’urgence : {n} dossiers ont été ouverts pour votre compte.',
    'Mit dem Firmen-Notfallkit schalten Sie alle Ordner für Ihr eigenes Konto frei, auf die Sie noch keinen Zugriff haben – etwa wenn alle Mitglieder eines Ordners ihren Zugang verloren haben. Der Vorgang wird protokolliert.' => 'Avec le kit d’urgence de l’entreprise, vous ouvrez pour votre propre compte tous les dossiers auxquels vous n’avez pas encore accès – par exemple si tous les membres d’un dossier ont perdu leur accès. L’opération est journalisée.',
    'Ordner freischalten' => 'Ouvrir les dossiers',
    'Automatisch sperren nach (Minuten ohne Aktivität)' => 'Verrouiller automatiquement après (minutes d’inactivité)',
    'Prüfwert des Firmen-Notfallschlüssels: {f}' => 'Empreinte de la clé d’urgence de l’entreprise : {f}',
    'Tresor-Zugang von {n} zurücksetzen? Die Person muss ihn neu einrichten und bekommt die Ordner danach automatisch wieder freigeschaltet, sobald ein Mitglied den Tresor öffnet.' => 'Réinitialiser l’accès au coffre-fort de {n} ? La personne doit le reconfigurer ; les dossiers lui sont rouverts automatiquement dès qu’un membre ouvre le coffre-fort.',
    'Der Tresor-Zugang wurde zurückgesetzt.' => 'L’accès au coffre-fort a été réinitialisé.',
    'Tresor-Einstellungen' => 'Paramètres du coffre-fort',
    'Tresor-Zugang zurücksetzen' => 'Réinitialiser l’accès au coffre-fort',
    'Nur nötig, wenn jemand Tresor-Passwort und Notfallkit verloren hat.' => 'Nécessaire uniquement si quelqu’un a perdu le mot de passe et le kit d’urgence.',
    'Keine weiteren Tresor-Zugänge.' => 'Aucun autre accès au coffre-fort.',
    'Das bisherige Tresor-Passwort ist falsch.' => 'Le mot de passe actuel du coffre-fort est incorrect.',
    'Ihr Tresor-Passwort wurde geändert.' => 'Votre mot de passe du coffre-fort a été modifié.',
    'Bisheriges Tresor-Passwort' => 'Mot de passe actuel du coffre-fort',
    'Mein Tresor-Zugang' => 'Mon accès au coffre-fort',
    'angezeigt' => 'affiché',
    'kopiert' => 'copié',
    'geändert' => 'modifié',
    'gelöscht' => 'supprimé',
    'beim Schlüsselwechsel neu verschlüsselt' => 'rechiffré lors du changement de clé',
    'Ohne Titel' => 'Sans titre',
    'Tresor: Zugangsdaten bald ändern' => 'Coffre-fort : identifiants à changer bientôt',
    'für diese Einträge im Tresor ist bald oder bereits ein Passwortwechsel fällig:' => 'un changement de mot de passe est bientôt dû ou déjà en retard pour ces entrées du coffre-fort :',
    'Ändern Sie das Passwort beim Dienst, tragen Sie es im Tresor ein und setzen Sie „Ändern bis“ neu.' => 'Changez le mot de passe auprès du service, enregistrez-le dans le coffre-fort et redéfinissez « À changer avant ».',
    'Zum Tresor:' => 'Accéder au coffre-fort :',
    'Exportieren dürfen nur die Administratoren der Firma.' => 'Seuls les administrateurs de l’entreprise peuvent exporter.',
    'Bitte zwischen 1 und 500 Einträge auf einmal importieren.' => 'Veuillez importer entre 1 et 500 entrées à la fois.',
    'Bald zu ändern' => 'À changer bientôt',
    'bis {d}' => 'avant le {d}',
    'Exportieren' => 'Exporter',
    'Aktueller 2FA-Code:' => 'Code 2FA actuel :',
    'noch {n} s' => 'encore {n} s',
    'Passwortwechsel alle {n} Monate.' => 'Changement de mot de passe tous les {n} mois.',
    'Generieren' => 'Générer',
    'Passwort wechseln' => 'Changer le mot de passe',
    'Mit Turnus wird „Ändern bis“ beim Speichern eines neuen Passworts automatisch neu gesetzt. 14 Tage vorher bekommen alle mit Bearbeiten-Recht eine E-Mail – nur mit Titel und Datum.' => 'Avec un intervalle, « À changer avant » est redéfini automatiquement à l’enregistrement d’un nouveau mot de passe. 14 jours avant, toutes les personnes autorisées à modifier reçoivent un e-mail – uniquement avec le titre et la date.',
    'Vorschlag' => 'Suggestion',
    'Zufällige Zeichen' => 'Caractères aléatoires',
    'Passphrase aus Wörtern' => 'Phrase de passe en mots',
    'Kleinbuchstaben' => 'Minuscules',
    'Großbuchstaben' => 'Majuscules',
    'Ziffern' => 'Chiffres',
    'Sonderzeichen' => 'Caractères spéciaux',
    'ohne verwechselbare Zeichen (l, I, O, 0, 1)' => 'sans caractères ambigus (l, I, O, 0, 1)',
    'Länge' => 'Longueur',
    'Anzahl Wörter' => 'Nombre de mots',
    'Passwort der Exportdatei' => 'Mot de passe du fichier d’export',
    'In der Datei wurden keine Einträge gefunden.' => 'Aucune entrée n’a été trouvée dans le fichier.',
    'Erkannt: {s} · {n} Einträge' => 'Détecté : {s} · {n} entrées',
    '… und {n} weitere' => '… et {n} de plus',
    'Tresor-Exportdatei' => 'Fichier d’export du coffre-fort',
    'Das Passwort der Exportdatei ist falsch.' => 'Le mot de passe du fichier d’export est incorrect.',
    '{n} Einträge wurden verschlüsselt importiert. Löschen Sie die Exportdatei jetzt von Ihrem Rechner.' => '{n} entrées ont été importées et chiffrées. Supprimez maintenant le fichier d’export de votre ordinateur.',
    '({n} Einträge wurden bereits importiert.)' => '({n} entrées ont déjà été importées.)',
    'In Ordner „{n}“ importieren' => 'Importer dans le dossier « {n} »',
    'Unterstützt: CSV-Export aus Bitwarden, KeePass, KeePassXC und 1Password sowie verschlüsselte Exportdateien dieses Tresors. Die Datei wird nur in Ihrem Browser gelesen und verschlüsselt; unverschlüsselt verlässt nichts Ihren Rechner.' => 'Pris en charge : exports CSV de Bitwarden, KeePass, KeePassXC et 1Password ainsi que les fichiers d’export chiffrés de ce coffre-fort. Le fichier est lu et chiffré uniquement dans votre navigateur ; rien ne quitte votre ordinateur en clair.',
    'Das Passwort der Exportdatei muss mindestens 12 Zeichen lang sein.' => 'Le mot de passe du fichier d’export doit comporter au moins 12 caractères.',
    'Bitte bestätigen Sie, dass die CSV-Datei unverschlüsselt ist.' => 'Veuillez confirmer que le fichier CSV n’est pas chiffré.',
    'Export erstellt. Die CSV-Datei ist unverschlüsselt – löschen Sie sie, sobald Sie sie nicht mehr brauchen.' => 'Export créé. Le fichier CSV n’est pas chiffré – supprimez-le dès que vous n’en avez plus besoin.',
    'Export erstellt. Die Datei ist mit Ihrem Export-Passwort verschlüsselt.' => 'Export créé. Le fichier est chiffré avec votre mot de passe d’export.',
    'Verschlüsselte Exportdatei (.kpvault) – lässt sich in diesen Tresor wieder importieren' => 'Fichier d’export chiffré (.kpvault) – réimportable dans ce coffre-fort',
    'Export-Passwort (mindestens 12 Zeichen)' => 'Mot de passe d’export (au moins 12 caractères)',
    'Export-Passwort wiederholen' => 'Répéter le mot de passe d’export',
    'CSV unverschlüsselt (Bitwarden-Format, z. B. für einen Umzug)' => 'CSV non chiffré (format Bitwarden, p. ex. pour une migration)',
    'Mir ist klar, dass die CSV-Datei alle Passwörter im Klartext enthält.' => 'Je comprends que le fichier CSV contient tous les mots de passe en clair.',
    'Der Export wird im Browser erzeugt. Jeder gelesene Eintrag und der Export selbst stehen im Protokoll.' => 'L’export est créé dans le navigateur. Chaque entrée lue et l’export lui-même sont journalisés.',
    'Ordner „{n}“ exportieren' => 'Exporter le dossier « {n} »',
    'exportiert' => 'exporté',
    'Dokumentation & Zugangsdaten' => 'Documentation et identifiants',
    'Noch keine Anleitungen oder Zugangsdaten verknüpft.' => 'Aucun guide ni identifiant lié pour l’instant.',
    '{n} weitere Verknüpfungen sind für Sie nicht sichtbar.' => '{n} autres liens ne vous sont pas visibles.',
    'Anleitung verknüpfen' => 'Lier un guide',
    '– Seite wählen –' => '– choisir une page –',
    'Zugangsdaten verknüpfen' => 'Lier des identifiants',
    '– Eintrag wählen –' => '– choisir une entrée –',
    'Es gibt noch keine Seiten oder Tresor-Einträge, die Sie verknüpfen können.' => 'Il n’y a pas encore de pages ni d’entrées du coffre-fort que vous pouvez lier.',
    'entfernen' => 'retirer',
    'Verknüpft.' => 'Lié.',
    'Bitte eine Seite oder einen Tresor-Eintrag wählen.' => 'Veuillez choisir une page ou une entrée du coffre-fort.',
    'Verknüpft mit' => 'Lié à',
    'Als Anleitung übernehmen' => 'Transformer en guide',
    'Entwurf anlegen' => 'Créer un brouillon',
    'Legt einen Entwurf mit Problem und Lösung aus diesem Ticket an. Interne Notizen werden nicht übernommen. Bitte vor dem Veröffentlichen prüfen und Persönliches entfernen.' => 'Crée un brouillon avec le problème et la solution de ce ticket. Les notes internes ne sont pas reprises. Veuillez le relire et retirer les informations personnelles avant de le publier.',
    'Übernommen aus Ticket #{n} vom {d}.' => 'Repris du ticket n° {n} du {d}.',
    'Problem' => 'Problème',
    'Der Entwurf wurde angelegt und mit dem Ticket verknüpft. Prüfen und ergänzen Sie ihn, bevor Sie ihn veröffentlichen.' => 'Le brouillon a été créé et lié au ticket. Relisez-le et complétez-le avant de le publier.',
    'Zugangsdaten ändern' => 'Changer les identifiants',
    'Zu diesem Auftrag wurde kein Portal-Konto gefunden (über die E-Mail-Adresse in der Mitarbeiterliste). Ohne Konto gibt es keine Tresor-Zugriffe.' => 'Aucun compte du portail n’a été trouvé pour cette demande (via l’adresse e-mail de la liste du personnel). Sans compte, il n’y a pas d’accès au coffre-fort.',
    '{n} hat keine Tresor-Einträge angezeigt oder kopiert, die Sie bearbeiten dürfen.' => '{n} n’a affiché ni copié aucune entrée du coffre-fort que vous pouvez modifier.',
    '{n} hat diese Zugangsdaten angezeigt oder kopiert. Ändern Sie die Passwörter beim jeweiligen Dienst und tragen Sie sie im Tresor neu ein.' => '{n} a affiché ou copié ces identifiants. Changez les mots de passe auprès du service concerné et enregistrez-les à nouveau dans le coffre-fort.',
    'Eintrag' => 'Entrée',
    'Zuletzt angesehen' => 'Dernière consultation',
    'zurücknehmen' => 'annuler',
    'Passwort geändert' => 'Mot de passe changé',
    'Der Zugriff auf den Tresor endet automatisch, sobald das Konto deaktiviert oder aus den Gruppen entfernt wird; die betroffenen Ordner werden dann neu verschlüsselt.' => 'L’accès au coffre-fort prend fin automatiquement dès que le compte est désactivé ou retiré des groupes ; les dossiers concernés sont alors rechiffrés.',
    'Der verknüpfte Eintrag ist für Sie nicht freigegeben.' => 'L’entrée liée ne vous est pas ouverte.',
    // Zentrale Einstellungen
    'Mitarbeiter-Onboarding' => 'Intégration des collaborateurs',
    // Zentrale Einstellungen, Stufe 2: Einsicht und Datensicherung
    'Für diese Firma ist keine App mit Einsicht-Schalter freigeschaltet.' => 'Aucune application avec un interrupteur d’accès prestataire n’est activée pour cette entreprise.',
    'Es gab keine Änderungen.' => 'Aucune modification.',
    'Hier legen Sie fest, in welche Apps Ihr IT-Dienstleister Einblick bekommt. Ausschalten wirkt sofort. Was er im Einzelnen darf, regeln seine eigenen Rechte; der Schalter ist Ihre Freigabe.' => 'Choisissez les applications auxquelles votre prestataire informatique a accès. La désactivation prend effet immédiatement. Ce qu’il peut faire en détail dépend de ses propres droits ; l’interrupteur est votre autorisation.',
    'App' => 'Application',
    'Einsicht' => 'Accès',
    'wenn eingeschaltet' => 'si activé',
    'zuletzt geändert' => 'dernière modification',
    'Zusatzfreigaben gelten nur, solange die Einsicht für die App eingeschaltet ist. Ihre eigenen Rechte über Gruppen gelten unabhängig davon.' => 'Les autorisations supplémentaires ne s’appliquent que tant que l’accès à l’application est activé. Vos propres droits par groupe s’appliquent indépendamment.',
    'Einsicht für den IT-Dienstleister:' => 'Accès pour le prestataire informatique :',
    'unter Einstellungen ändern' => 'modifier dans les paramètres',
    'Ihre Anfrage ist bereits bei Ihrem IT-Dienstleister.' => 'Votre demande a déjà été transmise à votre prestataire informatique.',
    'App-Anfrage: Datensicherung für {x}' => 'Demande d’application : Sauvegarde pour {x}',
    'Die Firma „{x}“ möchte die App „Datensicherung“ nutzen.

Angefragt von: {n} <{m}>

Freischalten:
' => 'L’entreprise « {x} » souhaite utiliser l’application « Sauvegarde ».

Demandé par : {n} <{m}>

Activer :
',
    'Ihre Anfrage wurde an Ihren IT-Dienstleister gesendet.' => 'Votre demande a été envoyée à votre prestataire informatique.',
    'Die App „Datensicherung“ ist für Ihre Firma noch nicht freigeschaltet. Ihr IT-Dienstleister kann sie für Sie freischalten.' => 'L’application « Sauvegarde » n’est pas encore activée pour votre entreprise. Votre prestataire informatique peut l’activer pour vous.',
    'Zuletzt angefragt am {d}.' => 'Dernière demande le {d}.',
    'Freischaltung anfragen' => 'Demander l’activation',
    'Zu den Sicherungen' => 'Vers les sauvegardes',
    'Tägliche Sicherung, Aufbewahrung, Fehler-Mail und Google Drive:' => 'Sauvegarde quotidienne, conservation, e-mail d’erreur et Google Drive :',
    'Die Mitarbeiter-Statistik kann nur ein Administrator der Firma ein- oder ausschalten.' => 'Seul un administrateur de l’entreprise peut activer ou désactiver les statistiques par collaborateur.',
    'Die Tickets dieser Firma sind nur intern sichtbar. Die Firma kann die Einsicht für den IT-Dienstleister unter Einstellungen einschalten. Tickets, die die Firma an Sie übergibt, sehen Sie unter „An uns übergeben“. Queues und Einstellungen können Sie trotzdem pflegen.' => 'Les tickets de cette entreprise ne sont visibles qu\'en interne. L\'entreprise peut autoriser l\'accès du prestataire informatique dans les paramètres. Les tickets que l\'entreprise vous transmet se trouvent sous « Transmis à nous ». Vous pouvez néanmoins gérer les files et les paramètres.',
    'Ihr IT-Dienstleister sieht und bearbeitet die Tickets Ihrer Firma. Tickets, die Sie ihm ausdrücklich übergeben, sieht er auch ohne Einsicht.' => 'Votre prestataire informatique voit et traite les tickets de votre entreprise. Les tickets que vous lui transmettez explicitement lui restent visibles même sans accès.',
    'Ihr IT-Dienstleister sieht und pflegt Ihr Inventar und bekommt die Erinnerungen zu Lizenzen und Garantien.' => 'Votre prestataire informatique voit et gère votre inventaire et reçoit les rappels de licences et de garanties.',
    'Ihr IT-Dienstleister sieht und pflegt Ihre Verträge und bekommt die Fristen der Verträge, die er betreut.' => 'Votre prestataire informatique voit et gère vos contrats et reçoit les échéances des contrats qu’il gère.',
    'Ihr IT-Dienstleister sieht und pflegt Ihr Wiki. Den Passwort-Tresor sieht er nur in Ordnern, in die Sie ihn ausdrücklich aufnehmen.' => 'Votre prestataire informatique voit et gère votre wiki. Dans le coffre-fort de mots de passe, il ne voit que les dossiers auxquels vous l’ajoutez explicitement.',
];
